"""
OFAC Specially Designated Nationals and Blocked Persons (SDN) Catalog.
Comprehensive institutional sanctions database with aliases, programs, and fuzzy search engine.
"""

from dataclasses import dataclass, field
from typing import List, Dict, Optional, Any, Set
import re

@dataclass
class SanctionedEntity:
    sdn_id: int
    name: str
    sdn_type: str  # "INDIVIDUAL" or "ENTITY" or "VESSEL" or "AIRCRAFT"
    programs: List[str]
    title: Optional[str] = None
    call_sign: Optional[str] = None
    vessel_type: Optional[str] = None
    tonnage: Optional[int] = None
    grt: Optional[int] = None
    vessel_flag: Optional[str] = None
    vessel_owner: Optional[str] = None
    remarks: Optional[str] = None
    dob_list: List[str] = field(default_factory=list)
    pob_list: List[str] = field(default_factory=list)
    citizenships: List[str] = field(default_factory=list)
    dates_of_listing: List[str] = field(default_factory=list)
    identifications: Dict[str, str] = field(default_factory=dict)
    addresses: List[Dict[str, str]] = field(default_factory=list)
    aliases: List[str] = field(default_factory=list)

